with greek_translations (slug, overlay) as (
  values
  ('kriopigi-villas', $el${"title":"Kriopigi Villas","address":"Παραλία Κρυοπηγής, Χαλκιδική","cardAddress":"Εκεί όπου η πολυτέλεια συναντά το Αιγαίο","price":"από 495.000 €","shortDescription":"Καλώς ήρθατε σε μια αποκλειστική συλλογή μόλις τεσσάρων ιδιωτικών βιλών, σε προνομιακή θέση στην περίφημη πρώτη γραμμή της Χαλκιδικής. Απολαύστε πανοραμική θέα στη θάλασσα από μια υπερυψωμένη τοποθεσία πάνω στον γκρεμό, ευρύχωρα ιδιωτικά οικόπεδα άνω των 1.000 m², κομψούς σύγχρονους εσωτερικούς χώρους και τη δική σας ιδιωτική πισίνα. Σε απόσταση λίγων μόλις βημάτων από μια κρυφή, παρθένα παραλία, οι κατοικίες προσφέρουν την ιδανική ισορροπία ιδιωτικότητας, φυσικής ομορφιάς και εκλεπτυσμένης παραθαλάσσιας ζωής. Ξυπνήστε με το απέραντο γαλάζιο του Αιγαίου. Επιστρέψτε σε μια ζωή πέρα από κάθε προσδοκία","fullDescription":"Καλώς ήρθατε στο Kriopigi Villas — μια αυστηρά περιορισμένη συλλογή μόλις τεσσάρων ανεξάρτητων παραθαλάσσιων βιλών από τη MIRACON Constructions\n\nΣε ένα απομονωμένο καταφύγιο στην παρθένα ακτογραμμή της Κασσάνδρας, κάθε βίλα προσφέρει ανεμπόδιστη πανοραμική θέα στο Αιγαίο, απόλυτη ιδιωτικότητα και ιδιωτική πισίνα — σε μικρή απόσταση με τα πόδια από μια ανέγγιχτη ιδιωτική παραλία","introTitle":"Εκεί όπου αρχίζει η ζωή σας δίπλα στη θάλασσα","walkthroughVideoTitle":"Εικονική περιήγηση","nearbyPlaces":["Αιγαίο Πέλαγος · Πανοραμική θέα","Ιδιωτική παραλία · Σε μικρή απόσταση με τα πόδια","Ακτογραμμή Κασσάνδρας · Απομονωμένο καταφύγιο","Πευκοδάσος · Φυσική ιδιωτικότητα","Ιδιωτικές πισίνες · Σε κάθε βίλα","Τρόπος ζωής στη Χαλκιδική · Παραθαλάσσια διαβίωση"],"seoTitle":"Kriopigi Villas — MIRACON","seoDescription":"Τέσσερις ανεξάρτητες παραθαλάσσιες βίλες στην Κασσάνδρα Χαλκιδικής, με ιδιωτικές πισίνες και πανοραμική θέα στο Αιγαίο.","characteristics":{"bedrooms":{"label":"Υπνοδωμάτια","value":"2-3"},"bathrooms":{"label":"Μπάνια","value":"1-2"},"area":{"label":"Εμβαδόν","value":"110-175 m²"},"levels":{"label":"Επίπεδα","value":"2-3"}},"benefits":{"shore":{"title":"Τοποθεσία στην πρώτη γραμμή της θάλασσας"},"villas":{"title":"Μόλις 4 αποκλειστικές βίλες"},"pool":{"title":"Ιδιωτική πισίνα"},"forest":{"title":"Μέσα σε πευκοδάσος"},"views":{"title":"Πανοραμική θέα στον κόλπο"},"levels":{"title":"Διώροφες και τριώροφες βίλες"},"kitchen":{"title":"Πλήρως εξοπλισμένη κουζίνα"},"finishes":{"title":"Φινιρίσματα σχεδιαστικών προδιαγραφών"}},"floorPlanGroups":{"two-level":{"title":"Διώροφη βίλα 110 m²","plans":{"two-level-1":{"title":"Επίπεδο 1","alt":"Κάτοψη 1ου επιπέδου διώροφης βίλας"},"two-level-2":{"title":"Επίπεδο 2","alt":"Κάτοψη 2ου επιπέδου διώροφης βίλας"}}},"three-level":{"title":"Τριώροφη βίλα 175 m²","plans":{"three-level-1":{"title":"Επίπεδο 1","alt":"Κάτοψη 1ου επιπέδου τριώροφης βίλας"},"three-level-2":{"title":"Επίπεδο 2","alt":"Κάτοψη 2ου επιπέδου τριώροφης βίλας"},"three-level-3":{"title":"Επίπεδο 3","alt":"Κάτοψη 3ου επιπέδου τριώροφης βίλας"}}}},"imageAlts":{"kriopigi-card-1":"Εξωτερική άποψη του Kriopigi Villas","kriopigi-card-2":"Η ακτογραμμή στο Kriopigi Villas","kriopigi-card-3":"Εσωτερικός χώρος στο Kriopigi Villas","kriopigi-gallery-1":"Εσωτερικός χώρος τραπεζαρίας στο Kriopigi Villas","kriopigi-gallery-2":"Εσωτερικός χώρος κουζίνας και τραπεζαρίας στο Kriopigi Villas","kriopigi-gallery-3":"Εξωτερική άποψη βίλας με ιδιωτική πισίνα στο Kriopigi Villas","kriopigi-gallery-4":"Πρόσοψη βίλας προς τον κήπο στο Kriopigi Villas","kriopigi-gallery-5":"Εσωτερικός χώρος υπνοδωματίου στο Kriopigi Villas","kriopigi-gallery-6":"Σουίτα υπνοδωματίου στο Kriopigi Villas","kriopigi-gallery-7":"Κήπος εισόδου στο Kriopigi Villas","kriopigi-gallery-8":"Απεικόνιση εσωτερικού χώρου στο Kriopigi Villas","kriopigi-gallery-9":"Λεπτομέρεια εσωτερικού χώρου στο Kriopigi Villas"}}$el$::jsonb),
  ('olympus-sea-view', $el${"title":"Olympus Sea View","address":"Περαία, Θεσσαλονίκη","cardAddress":"Παραθαλάσσια τοποθεσία στην Περαία","price":"από 143.000 €","shortDescription":"Ένα κορυφαίο παραθαλάσσιο συγκρότημα στην πρώτη γραμμή της Περαίας. Πέντε ολοκαίνουργια κτίρια, 30 σύγχρονες μονάδες: διαμερίσματα, στούντιο και διώροφες μεζονέτες με πανοραμική θέα στη θάλασσα από το ιδιωτικό μπαλκόνι. 30 λεπτά από το κέντρο της Θεσσαλονίκης. 20 λεπτά από το Αεροδρόμιο Θεσσαλονίκης. Λίγα μόλις βήματα από το Αιγαίο Πέλαγος","fullDescription":"Καλώς ήρθατε στο Olympus Sea View — ένα κορυφαίο παραθαλάσσιο συγκρότημα κατοικιών στην πρώτη γραμμή της Περαίας\n\nΣχεδιασμένο για όσους αναζητούν την ιδανική ισορροπία ανάμεσα στην ηρεμία της παραθαλάσσιας ζωής και τη σύγχρονη άνεση, προσφέρει αποκλειστικότητα, φινιρίσματα υψηλών προδιαγραφών και εκπληκτική θέα στη θάλασσα. Όλα τα κτίρια διαθέτουν ανελκυστήρες","introTitle":"Εκεί όπου αρχίζει η ζωή σας δίπλα στη θάλασσα","walkthroughVideoTitle":"Εικονική περιήγηση","nearbyPlaces":["Θερμαϊκός Κόλπος · Άμεση πρόσβαση","Ελληνικές ταβέρνες · Λίγα βήματα μακριά","Καταστήματα και καφέ · 100 m","Κέντρο Θεσσαλονίκης · 30 λεπτά","Αεροδρόμιο Θεσσαλονίκης · 35 km","Παραλία · Πρώτη γραμμή"],"seoTitle":"Olympus Sea View — MIRACON","seoDescription":"Παραθαλάσσια διαμερίσματα στην Περαία, με πανοραμική θέα στη θάλασσα και φινιρίσματα υψηλών προδιαγραφών.","characteristics":{"bedrooms":{"label":"Υπνοδωμάτια","value":"1-2"},"bathrooms":{"label":"Μπάνια","value":"1-2"},"area":{"label":"Εμβαδόν","value":"44-123 m²"},"levels":{"label":"Επίπεδα","value":"1-2"}},"benefits":{"shore":{"title":"Τοποθεσία στην πρώτη γραμμή της θάλασσας"},"apartments":{"title":"30 σύγχρονα διαμερίσματα"},"ready":{"title":"Έτοιμα για κατοίκηση"},"glazing":{"title":"Υαλοστάσια από το δάπεδο έως την οροφή"},"balcony":{"title":"Ιδιωτικό μπαλκόνι ή βεράντα"},"city":{"title":"30 λεπτά από τη Θεσσαλονίκη"},"views":{"title":"Θέα στη θάλασσα από κάθε κατοικία"},"finish":{"title":"Φινιρίσματα και σχεδιασμός υψηλών προδιαγραφών"}},"floorPlanGroups":{"duplex":{"title":"Τυπική μεζονέτα 123 m²","plans":{"duplex-1":{"title":"Επίπεδο 1","alt":"Κάτοψη 1ου επιπέδου μεζονέτας"},"duplex-2":{"title":"Επίπεδο 2","alt":"Κάτοψη 2ου επιπέδου μεζονέτας"}}},"studio":{"title":"Τυπικό στούντιο 44 m²","plans":{"studio-1":{"title":"Τυπικό στούντιο 44 m²","alt":"Κάτοψη τυπικού στούντιο"}}},"apartment":{"title":"Τυπικό διαμέρισμα 44 m²","plans":{"apartment-1":{"title":"Τυπικό διαμέρισμα 44 m²","alt":"Κάτοψη τυπικού διαμερίσματος"}}}},"imageAlts":{"olympus-card-1":"Το συγκρότημα κτιρίων Olympus Sea View","olympus-card-2":"Μπαλκόνι στο Olympus Sea View","olympus-card-3":"Υπνοδωμάτιο στο Olympus Sea View","olympus-gallery-1":"Βεράντα στο Olympus Sea View","olympus-gallery-2":"Η ακτογραμμή στο Olympus Sea View","olympus-gallery-3":"Κεντρική εξωτερική άποψη του Olympus Sea View","olympus-gallery-4":"Πλάγια εξωτερική άποψη του Olympus Sea View"}}$el$::jsonb),
  ('artemis-residences', $el${"title":"Artemis Residences","address":"Νέα Καλλικράτεια, Χαλκιδική","cardAddress":"Νέα Καλλικράτεια, Χαλκιδική","price":"από 177.000 €","shortDescription":"Ετοιμοπαράδοτα διαμερίσματα υψηλών προδιαγραφών στη δημοφιλή παραθαλάσσια πόλη της Νέας Καλλικράτειας, 400 m από την παραλία. Διαθέσιμες οι τελευταίες 2 μεζονέτες. Περιλαμβάνουν αποκλειστική θέση στάθμευσης και ιδιωτική αποθήκη","fullDescription":"Μια boutique κατοικία υψηλών προδιαγραφών από τη MIRACON Constructions, στην καρδιά της Νέας Καλλικράτειας — ενός από τους δημοφιλέστερους παραθαλάσσιους προορισμούς, σε απόσταση μίας ώρας οδικώς από τη Θεσσαλονίκη. Το κτίριο διαθέτει ανελκυστήρα\n\nΜόλις 400 μέτρα από την παραλία της Νέας Καλλικράτειας, το Artemis προσφέρει τον ιδανικό συνδυασμό παραθαλάσσιας χαλάρωσης και σύγχρονης άνεσης","introTitle":"Σύγχρονη ζωή δίπλα στη θάλασσα","walkthroughVideoTitle":"Εικονική περιήγηση","nearbyPlaces":["Θάλασσα · 400 m","Νέα Καλλικράτεια · Κεντρική τοποθεσία","Θέση στάθμευσης · Περιλαμβάνεται","Ιδιωτική αποθήκη · Περιλαμβάνεται"],"seoTitle":"Artemis Residences — MIRACON","seoDescription":"Ετοιμοπαράδοτα διαμερίσματα υψηλών προδιαγραφών στη Νέα Καλλικράτεια, κοντά στη θάλασσα.","benefits":{"shore":{"title":"400 μέτρα από τη θάλασσα"},"availability":{"title":"Διαθέσιμες οι τελευταίες 2 μεζονέτες"},"ready":{"title":"Έτοιμα για κατοίκηση"},"parking":{"title":"Αποκλειστική θέση στάθμευσης"},"storage":{"title":"Ιδιωτική αποθήκη"},"location":{"title":"Τοποθεσία στη Νέα Καλλικράτεια"}},"imageAlts":{"artemis-card-1":"Εξωτερική άποψη του Artemis Residences","artemis-card-2":"Καθιστικό στο Artemis Residences","artemis-card-3":"Βεράντα στο Artemis Residences"}}$el$::jsonb),
  ('monastiriou-4-residences', $el${"title":"Monastiriou 4 Residences","address":"Μοναστηρίου 4 · Κέντρο Θεσσαλονίκης","cardAddress":"Μοναστηρίου 4 · Κέντρο Θεσσαλονίκης","price":"από 165.000 €","shortDescription":"Σύγχρονα αστικά διαμερίσματα στην καρδιά της Θεσσαλονίκης. Υψηλή ζήτηση για μίσθωση όλο τον χρόνο από φοιτητές, επαγγελματίες και τουρίστες. Επιλέξιμα για Golden Visa από 250.000 €","fullDescription":"Στο κέντρο της Θεσσαλονίκης, μια νέα οικιστική πρόταση — το Monastiriou 4 Residences — μεταμορφώνει πρώην επαγγελματικούς χώρους σε κομψές, σύγχρονες κατοικίες\n\nΣε μια ιδιαίτερα κεντρική περιοχή υψηλής ζήτησης, το έργο προσφέρει ισχυρές προοπτικές μίσθωσης (μακροχρόνιας και βραχυχρόνιας), εγγύτητα σε βασικές υποδομές και σταθερή ζήτηση από φοιτητές, επαγγελματίες και τουρίστες","introTitle":"Στρατηγική τοποθεσία. Έξυπνη επένδυση","walkthroughVideoTitle":"Εικονική περιήγηση","nearbyPlaces":["Κέντρο Θεσσαλονίκης · Σε κοντινή απόσταση με τα πόδια","Μετακινήσεις · Άμεση πρόσβαση","Ζήτηση για μίσθωση · Όλο τον χρόνο","Golden Visa · Επιλέξιμες μονάδες"],"seoTitle":"Monastiriou 4 Residences — MIRACON","seoDescription":"Σύγχρονα αστικά διαμερίσματα και επενδυτικές ευκαιρίες Golden Visa στη Θεσσαλονίκη.","characteristics":{"bedrooms":{"label":"Υπνοδωμάτια","value":"1-2"},"bathrooms":{"label":"Μπάνια","value":"1-2"},"area":{"label":"Εμβαδόν","value":"44-123 m²"},"levels":{"label":"Επίπεδα","value":"1-2"}},"benefits":{"location":{"title":"Προνομιακή τοποθεσία"},"residences":{"title":"Σύγχρονες κατοικίες"},"ready":{"title":"Κατασκευή υψηλών προδιαγραφών"},"glazing":{"title":"Άπλετο φυσικό φως"},"balcony":{"title":"Ιδιωτικός εξωτερικός χώρος"},"access":{"title":"Τοποθεσία με άμεση πρόσβαση"},"views":{"title":"Ανεμπόδιστη θέα"},"finish":{"title":"Φινιρίσματα υψηλών προδιαγραφών"}},"imageAlts":{"monastiriou-card-1":"Εξωτερική άποψη του Monastiriou 4","monastiriou-card-2":"Μπροστινή άποψη του Monastiriou 4","monastiriou-card-3":"Πλάγια άποψη του Monastiriou 4"}}$el$::jsonb),
  ('giannitson-thessaloniki', $el${"title":"Giannitson Thessaloniki","address":"Κέντρο Θεσσαλονίκης","cardAddress":"Κέντρο Θεσσαλονίκης","price":"από 130.000 €","shortDescription":"Ένα εμβληματικό εννιαώροφο κτίριο κατοικιών με 32 σύγχρονα διαμερίσματα και αποκλειστικά διώροφα ρετιρέ. Καθαρές γραμμές, φινιρίσματα υψηλών προδιαγραφών και άπλετο φυσικό φως, σε μια αστική τοποθεσία με εξαιρετική σύνδεση","fullDescription":"Ένα εμβληματικό εννιαώροφο κτίριο κατοικιών με 32 σύγχρονα διαμερίσματα και αποκλειστικά διώροφα ρετιρέ, σε μια αστική τοποθεσία με εξαιρετική σύνδεση","introTitle":"Ένα νέο αστικό τοπόσημο","walkthroughVideoTitle":"Εικονική περιήγηση","nearbyPlaces":["Κέντρο Θεσσαλονίκης · Τοποθεσία με άμεση σύνδεση","Διαμερίσματα · 32 κατοικίες","Ρετιρέ · Διώροφες διαρρυθμίσεις","Φυσικό φως · Πανοραμικά υαλοστάσια"],"seoTitle":"Giannitson Thessaloniki — MIRACON","seoDescription":"Σύγχρονα διαμερίσματα και διώροφα ρετιρέ στο κέντρο της Θεσσαλονίκης.","characteristics":{"bedrooms":{"label":"Υπνοδωμάτια","value":"1-2"},"bathrooms":{"label":"Μπάνια","value":"1-2"},"area":{"label":"Εμβαδόν","value":"44-123 m²"},"levels":{"label":"Επίπεδα","value":"1-2"}},"benefits":{"location":{"title":"Προνομιακή τοποθεσία"},"residences":{"title":"Σύγχρονες κατοικίες"},"ready":{"title":"Κατασκευή υψηλών προδιαγραφών"},"glazing":{"title":"Άπλετο φυσικό φως"},"balcony":{"title":"Ιδιωτικός εξωτερικός χώρος"},"access":{"title":"Τοποθεσία με άμεση πρόσβαση"},"views":{"title":"Ανεμπόδιστη θέα"},"finish":{"title":"Φινιρίσματα υψηλών προδιαγραφών"}},"imageAlts":{"giannitson-card-1":"Ο πύργος Giannitson Thessaloniki","giannitson-card-2":"Εξωτερική άποψη του Giannitson Thessaloniki","giannitson-card-3":"Πλάγια άποψη του Giannitson Thessaloniki"}}$el$::jsonb)
),
