  ('artemis-residences', '{}'::jsonb, $plans${"1c8c800e-47e3-414f-a874-9745ccca44fe":{"title":"D16 - 66m²","plans":{"1ef8c021-8042-429b-9b2b-45c6394518f8":{"title":"Επίπεδο 1","alt":"Κάτοψη Artemis Residences"},"0b6605bb-4ba9-486d-8b18-b0178abe827a":{"title":"Επίπεδο 2","alt":"Κάτοψη Artemis Residences"}}},"4607e8d8-d669-4f16-8e98-0cbe2537176b":{"title":"D17 - 74m²","plans":{"78b5eea1-95d2-440f-86c5-4c656ec6fe9c":{"title":"Επίπεδο 1","alt":"Κάτοψη Artemis Residences"},"f8610c90-1f80-46cb-b3fc-b8022687a5df":{"title":"Επίπεδο 2","alt":"Κάτοψη Artemis Residences"}}},"0b9303d9-6cf9-4f06-9a28-7676cb25c86e":{"title":"D18 - 94m²","plans":{"a2a1eddc-d079-42ff-99b0-f7bd4dea0218":{"title":"Επίπεδο 1","alt":"Κάτοψη Artemis Residences"},"e139020a-0d84-4e00-8417-2971a5045622":{"title":"Επίπεδο 2","alt":"Κάτοψη Artemis Residences"}}}}$plans$::jsonb),
