  ('giannitson-thessaloniki', $benefits${"central-location":{"title":"Κεντρική τοποθεσία στη Θεσσαλονίκη"},"nine-storeys":{"title":"Εμβληματικό εννιαώροφο κτίριο κατοικιών"},"apartments":{"title":"32 σύγχρονα διαμερίσματα"},"penthouses":{"title":"Αποκλειστικά διώροφα ρετιρέ"},"natural-light":{"title":"Άπλετο φυσικό φως"},"architecture":{"title":"Σύγχρονη αρχιτεκτονική"},"finishes":{"title":"Φινιρίσματα υψηλών προδιαγραφών"},"connections":{"title":"Εξαιρετικές συγκοινωνιακές συνδέσεις"}}$benefits$::jsonb, $plans${"2ec8550e-027d-459d-b1aa-d2ba5cd31826":{"title":"Διώροφη βίλα 110 m²","plans":{"869417d5-08a2-4b57-b0e6-15db05a32345":{"title":"Επίπεδο 1","alt":"Κάτοψη Giannitson Thessaloniki"},"98b1613f-c2f8-4524-91f3-8e274571617b":{"title":"Κάτοψη","alt":"Κάτοψη Giannitson Thessaloniki"}}}}$plans$::jsonb)
)
update public.projects as projects
set translations = coalesce(projects.translations, '{}'::jsonb)
  || jsonb_build_object(
    'el',
    jsonb_set(
      jsonb_set(
        greek_translations.overlay,
        '{benefits}',
        coalesce(greek_translations.overlay->'benefits', '{}'::jsonb)
          || coalesce(greek_nested_translations.benefits, '{}'::jsonb),
        true
      ),
      '{floorPlanGroups}',
      coalesce(greek_translations.overlay->'floorPlanGroups', '{}'::jsonb)
        || coalesce(greek_nested_translations.floor_plan_groups, '{}'::jsonb),
      true
    )
  )
from greek_translations
left join greek_nested_translations using (slug)
where projects.slug = greek_translations.slug;
